WITH not_flagged AS (SELECT s.* FROM orders s WHERE EXISTS (SELECT 1 FROM order_items c WHERE c.order_id = s.id AND c.unit_price > 160)) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, DATE_TRUNC('WEEK', order_date) AS week_start, store_id, COUNT(*) AS event_count, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN channel = 'mobile' THEN 1 END), 0), 2) AS amount_per_mobile, CORR(discount, amount) AS corr_discount_amount FROM not_flagged GROUP BY DATE_TRUNC('QUARTER', order_date), DATE_TRUNC('WEEK', order_date), store_id HAVING ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN channel = 'mobile' THEN 1 END), 0), 2) >= 0
